python3 -c "
import json
data = json.load(open('/app/resources/treasury_bulletin_1991_09.json'))
# Print keys and some structure
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k)[:80])
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(d, list) and len(d) > 0 and indent < 2:
        print(' ' * indent + f'List of {len(d)} items')
        print_structure(d[0] if len(d) > 0 else {}, indent + 2)

print_structure(data)
" 2>/dev/null | head -100

